selector .elementor-icon-list-text, selector .elementor-icon-list-icon svg {
    padding: 0;
    margin: 0;
}

selector .elementor-icon-list-item {
    padding: 7px 16px;
    position: relative;
    border-radius: 9999px;
    isolation: isolate;
    background: rgba(21, 128, 61, 0.35);
}

selector .elementor-icon-list-item:before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: linear-gradient(90deg, #FFCC00 20%, #15803D 100%);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
  pointer-events: none;
  z-index: -1;
}

.marquee-section {
  --mq-gap: 56px;      /* khoảng cách giữa các mục */
}

@media (max-width: 1024px) {
  .marquee-section {
    overflow: hidden !important;
    justify-content: flex-start !important;
  }

  .marquee-section > .e-con-inner {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    justify-content: flex-start !important;
    width: max-content !important;
    max-width: none !important;
    gap: 0 !important;
    will-change: transform;
    animation: mq-scroll var(--mq-duration, 20s) linear infinite;
  }

  .marquee-section .elementor-widget {
    flex: 0 0 auto !important;
    width: auto !important;
    max-width: none !important;
    margin: 0 !important;
    padding-right: var(--mq-gap) !important;
    white-space: nowrap;
  }

  .marquee-section .elementor-heading-title {
    white-space: nowrap;
    margin: 0;
  }

  .marquee-section:hover > .e-con-inner {
    animation-play-state: paused;
  }
}

@keyframes mq-scroll {
  from { transform: translateX(0); }
  to   { transform: translateX(calc(-1 * var(--mq-distance, 50%))); }
}

@media (prefers-reduced-motion: reduce) {
  .marquee-section > .e-con-inner { animation: none !important; }
}

