.specs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    margin: 0 auto;
    border-top: 1px solid #e3e3e3;
  }
 
  .spec {
    display: grid;
    grid-template-columns: 150px 1fr;
    align-items: center;
    gap: 0px;
    padding: 18px 8px 18px 0px;
    border-bottom: 1px solid #e3e3e3;
  }
  
    .spec:nth-child(2n) {
        padding: 18px 0px 18px 8px;
    }
 
  .spec:nth-child(odd):not(.full) {
    border-right: 1px solid #e3e3e3;
  }
 
  .spec.full {
    grid-column: 1 / -1;
    grid-template-columns: 150px 1fr;
  }
 
  .label {
    color: #4a4a4a;
    font-weight: 400;
    font-family: inter;
    font-size: 15px;
  }
 
  .value {
    font-weight: 600;
    color: #111;
    font-family: inter;
    font-size: 15px;
  }
 

  @media (max-width: 600px) {
    .specs { grid-template-columns: 1fr; }
    .spec:nth-child(odd):not(.full) { border-right: none; }
    .spec,
    .spec.full { grid-template-columns: 130px 1fr; padding: 16px 8px; }
  }

